# Full tier only (RUN_FULL=1): the results regenerated by run_all.R must equal the committed ones.
snap <- Sys.getenv("RELEASE_SNAPSHOT")
root <- normalizePath(file.path(testthat::test_path(), "..", ".."))
rd <- function(d, f) {
  x <- read.csv(file.path(d, f), na.strings = "", colClasses = "character")   # compare as text first, then numbers
  x[] <- lapply(x, function(v) if (!anyNA(suppressWarnings(as.numeric(v[!is.na(v)]))) && !any(grepl("^0[0-9]", v), na.rm = TRUE)) as.numeric(v) else v)
  x
}

test_that("rerun reproduces the committed results", {
  skip_if(snap == "", "set RUN_FULL=1 to rerun the pipeline and compare")
  new <- file.path(root, "results")
  for (f in c("county_results.csv", "events.csv", "changepoints.csv", "pca_loadings.csv", "cluster_summary.csv", "table1_summary.csv"))
    expect_equal(rd(new, f), rd(snap, f), tolerance = 1e-8, info = f)
  expect_identical(rd(new, "county_results.csv")$cluster, rd(snap, "county_results.csv")$cluster)
})
